<?php
require_once __DIR__ . '/../includes/functions.php'; require_role(['admin','staff','cashier']);$id=(int)($_GET['id']??0);
$s=$conn->prepare('SELECT s.*,u.name cashier FROM sales s JOIN users u ON u.id=s.cashier_id WHERE s.id=?');$s->bind_param('i',$id);$s->execute();$sale=$s->get_result()->fetch_assoc();if(!$sale){http_response_code(404);exit('Receipt not found.');}
if(current_user()['role']==='cashier'&&(int)$sale['cashier_id']!==(int)current_user()['id']){http_response_code(403);exit('You cannot view another cashier’s receipt.');}
$s=$conn->prepare('SELECT si.*,p.name,p.product_code FROM sale_items si JOIN products p ON p.id=si.product_id WHERE si.sale_id=?');$s->bind_param('i',$id);$s->execute();$items=$s->get_result()->fetch_all(MYSQLI_ASSOC);
layout_header('Sales receipt');
?>
<section class="receipt card"><div class="receipt-head"><div class="receipt-logo">🏪</div><h2>AC Store</h2><p>Sales receipt</p></div><div class="receipt-meta"><span>Receipt</span><b><?= e($sale['receipt_no']) ?></b><span>Date</span><b><?= e($sale['created_at']) ?></b><span>Cashier</span><b><?= e($sale['cashier']) ?></b></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?= e($i['name']) ?><small><?= e($i['product_code']) ?></small></td><td><?= (int)$i['quantity'] ?></td><td><?= money((float)$i['unit_price']) ?></td><td><?= money((float)$i['line_total']) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="receipt-totals"><p><span>Total</span><b><?= money((float)$sale['total']) ?></b></p><p><span>Payment</span><b><?= money((float)$sale['payment_received']) ?></b></p><p><span>Change</span><b><?= money((float)$sale['change_amount']) ?></b></p></div><p class="center muted">Thank you! Please come again.</p><div class="actions no-print"><button class="btn" onclick="window.print()">Print receipt</button><a class="btn btn-outline" href="<?= BASE_URL ?>/cashier/pos.php">New sale</a></div></section>
<?php layout_footer(); ?>
